SELECT COUNT(DISTINCT enron_eval_enron_emailinfo.`from`) FROM (SELECT enron_eval_enron_emailinfo.`from` FROM (SELECT __source.`from` AS `from` FROM enron_eval.enron_emailinfo AS __source) AS enron_eval_enron_emailinfo) AS enron_eval_enron_emailinfo
SELECT COUNT(1) AS `count(*)` FROM (SELECT __source.body AS body, __source.`date` AS `date`, __source.`from` AS `from`, __source.`id` AS `id`, __source.messageid AS messageid, __source.subject AS subject, __source.`to` AS `to`, __source.xfrom AS xfrom, __source.xto AS xto FROM enron_eval.enron_emailinfo AS __source) AS enron_eval_enron_emailinfo
SELECT enron_eval_enron_emailinfo.`id`, enron_eval_enron_emailinfo.messageid, enron_eval_enron_emailinfo.`from` FROM (SELECT enron_eval_enron_emailinfo.`from`, enron_eval_enron_emailinfo.`id`, enron_eval_enron_emailinfo.messageid, enron_eval_enron_emailinfo.subject FROM (SELECT __source.`from` AS `from`, __source.`id` AS `id`, __source.messageid AS messageid, __source.subject AS subject FROM enron_eval.enron_emailinfo AS __source) AS enron_eval_enron_emailinfo) AS enron_eval_enron_emailinfo WHERE enron_eval_enron_emailinfo.subject IS NULL OR TRIM(enron_eval_enron_emailinfo.subject) = '' ORDER BY CASE WHEN enron_eval_enron_emailinfo.`id` IS NULL THEN 1 ELSE 0 END, enron_eval_enron_emailinfo.`id` ASC
SELECT COUNT(1) AS `count(*)` FROM (SELECT enron_eval_enron_emailinfo.subject FROM (SELECT __source.subject AS subject FROM enron_eval.enron_emailinfo AS __source) AS enron_eval_enron_emailinfo) AS enron_eval_enron_emailinfo WHERE LOWER(enron_eval_enron_emailinfo.subject) LIKE 're:%' AND NOT enron_eval_enron_emailinfo.subject IS NULL AND enron_eval_enron_emailinfo.subject <> ''
SELECT COUNT(1) AS `count(*)` FROM (SELECT enron_eval_enron_emailinfo.xfrom FROM (SELECT __source.xfrom AS xfrom FROM enron_eval.enron_emailinfo AS __source) AS enron_eval_enron_emailinfo) AS enron_eval_enron_emailinfo WHERE LOWER(enron_eval_enron_emailinfo.xfrom) = LOWER('Phillip Allen')
SELECT ranked_mailboxes.mailbox, ranked_mailboxes.`count`, ranked_mailboxes.`rank` FROM (SELECT enron_eval_enron_email.mailbox, COUNT(1) AS `count`, DENSE_RANK() OVER (ORDER BY COUNT(1) DESC) AS `rank` FROM (SELECT enron_eval_enron_email.mailbox FROM (SELECT __source.mailbox AS mailbox FROM enron_eval.enron_email AS __source) AS enron_eval_enron_email) AS enron_eval_enron_email GROUP BY enron_eval_enron_email.mailbox) AS ranked_mailboxes WHERE ranked_mailboxes.`rank` <= 10
SELECT COUNT(1) AS `count(*)` FROM (SELECT enron_eval_enron_email.mailbox FROM (SELECT __source.mailbox AS mailbox FROM enron_eval.enron_email AS __source) AS enron_eval_enron_email) AS enron_eval_enron_email WHERE enron_eval_enron_email.mailbox = 'sent'
SELECT COUNT(1) AS `count(*)` FROM (SELECT enron_eval_enron_emailinfo.body FROM (SELECT __source.body AS body FROM enron_eval.enron_emailinfo AS __source) AS enron_eval_enron_emailinfo) AS enron_eval_enron_emailinfo WHERE LOWER(enron_eval_enron_emailinfo.body) LIKE '%california%'
SELECT ranked_source.`id`, ranked_source.source_file_id, ranked_source.source_name, ranked_source.`rank` FROM (SELECT enron_eval_enron_source.`id`, enron_eval_enron_source.source_file_id, enron_eval_enron_source.source_name, DENSE_RANK() OVER (ORDER BY CASE WHEN enron_eval_enron_source.`id` IS NULL THEN 1 ELSE 0 END, enron_eval_enron_source.`id` ASC) AS `rank` FROM (SELECT enron_eval_enron_source.`id`, enron_eval_enron_source.source_file_id, enron_eval_enron_source.source_name FROM (SELECT __source.`id` AS `id`, __source.source_file_id AS source_file_id, __source.source_name AS source_name FROM enron_eval.enron_source AS __source) AS enron_eval_enron_source) AS enron_eval_enron_source) AS ranked_source WHERE ranked_source.`rank` <= 10
SELECT DISTINCT enron_eval_enron_email.mailbox FROM (SELECT enron_eval_enron_email.mailbox FROM (SELECT __source.mailbox AS mailbox FROM enron_eval.enron_email AS __source) AS enron_eval_enron_email) AS enron_eval_enron_email WHERE NOT enron_eval_enron_email.mailbox IS NULL AND TRIM(enron_eval_enron_email.mailbox) <> '' ORDER BY CASE WHEN enron_eval_enron_email.mailbox IS NULL THEN 1 ELSE 0 END, enron_eval_enron_email.mailbox ASC
SELECT enron_eval_enron_emailinfo.`date`, enron_eval_enron_emailinfo.subject, enron_eval_enron_emailinfo.`from`, DENSE_RANK() OVER (ORDER BY enron_eval_enron_emailinfo.`date` DESC) AS `rank` FROM (SELECT enron_eval_enron_emailinfo.`date`, enron_eval_enron_emailinfo.`from`, enron_eval_enron_emailinfo.subject FROM (SELECT __source.`date` AS `date`, __source.`from` AS `from`, __source.subject AS subject FROM enron_eval.enron_emailinfo AS __source) AS enron_eval_enron_emailinfo) AS enron_eval_enron_emailinfo INNER JOIN (SELECT DISTINCT enron_eval_enron_emailinfo.`date` FROM (SELECT enron_eval_enron_emailinfo.`date`, enron_eval_enron_emailinfo.`from`, enron_eval_enron_emailinfo.subject FROM (SELECT __source.`date` AS `date`, __source.`from` AS `from`, __source.subject AS subject FROM enron_eval.enron_emailinfo AS __source) AS enron_eval_enron_emailinfo) AS enron_eval_enron_emailinfo ORDER BY enron_eval_enron_emailinfo.`date` DESC LIMIT 10) AS top_dates ON enron_eval_enron_emailinfo.`date` = top_dates.`date`
SELECT COUNT(DISTINCT enron_eval_enron_emailinfo.`id`) FROM (SELECT enron_eval_enron_emailinfo.`date`, enron_eval_enron_emailinfo.`id` FROM (SELECT __source.`date` AS `date`, __source.`id` AS `id` FROM enron_eval.enron_emailinfo AS __source) AS enron_eval_enron_emailinfo) AS enron_eval_enron_emailinfo WHERE SUBSTRING(enron_eval_enron_emailinfo.`date`, 1, 4) = '2001'
SELECT COUNT(CASE WHEN (NOT enron_eval_enron_emailorig.xfrom IS NULL AND (enron_eval_enron_emailorig.xfrom <> '')) THEN 1 END) AS xfrom_non_empty_count, COUNT(CASE WHEN (NOT enron_eval_enron_emailorig.xto IS NULL AND (enron_eval_enron_emailorig.xto <> '')) THEN 1 END) AS xto_non_empty_count FROM (SELECT enron_eval_enron_emailorig.xfrom, enron_eval_enron_emailorig.xto FROM (SELECT __source.xfrom AS xfrom, __source.xto AS xto FROM enron_eval.enron_emailorig AS __source) AS enron_eval_enron_emailorig) AS enron_eval_enron_emailorig
SELECT DISTINCT enron_eval_enron_source.xorigin FROM (SELECT enron_eval_enron_source.xorigin FROM (SELECT __source.xorigin AS xorigin FROM enron_eval.enron_source AS __source) AS enron_eval_enron_source) AS enron_eval_enron_source WHERE NOT enron_eval_enron_source.xorigin IS NULL AND enron_eval_enron_source.xorigin <> ''
SELECT COUNT(DISTINCT enron_eval_enron_email.mailbox) FROM (SELECT enron_eval_enron_email.mailbox, enron_eval_enron_email.people FROM (SELECT __source.mailbox AS mailbox, __source.people AS people FROM enron_eval.enron_email AS __source) AS enron_eval_enron_email) AS enron_eval_enron_email WHERE enron_eval_enron_email.people = 'campbell-l' AND NOT enron_eval_enron_email.mailbox IS NULL AND TRIM(enron_eval_enron_email.mailbox) <> ''
SELECT MAX(subquery.count_per_mailbox) FROM (SELECT COUNT(1) AS count_per_mailbox FROM (SELECT enron_eval_enron_email.mailbox FROM (SELECT __source.mailbox AS mailbox FROM enron_eval.enron_email AS __source) AS enron_eval_enron_email) AS enron_eval_enron_email GROUP BY enron_eval_enron_email.mailbox) AS subquery
