SELECT ranked_emails.`id`, ranked_emails.nnn, ranked_emails.subject, ranked_emails.`from`, ranked_emails.`rank` FROM (SELECT enron_eval_enron_email.`id`, enron_eval_enron_email.nnn, enron_eval_enron_emailinfo.subject, enron_eval_enron_emailinfo.`from`, DENSE_RANK() OVER (ORDER BY enron_eval_enron_email.nnn DESC, enron_eval_enron_email.`id` DESC) AS `rank` FROM (SELECT enron_eval_enron_email.`id`, enron_eval_enron_email.mailbox, enron_eval_enron_email.nnn, enron_eval_enron_email.people FROM (SELECT __source.`id` AS `id`, __source.mailbox AS mailbox, __source.nnn AS nnn, __source.people AS people FROM enron_eval.enron_email AS __source) AS enron_eval_enron_email) AS enron_eval_enron_email INNER JOIN (SELECT enron_eval_enron_emailinfo.`from`, enron_eval_enron_emailinfo.`id`, enron_eval_enron_emailinfo.subject FROM (SELECT __source.`from` AS `from`, __source.`id` AS `id`, __source.subject AS subject FROM enron_eval.enron_emailinfo AS __source) AS enron_eval_enron_emailinfo) AS enron_eval_enron_emailinfo ON enron_eval_enron_email.`id` = enron_eval_enron_emailinfo.`id` WHERE LOWER(enron_eval_enron_email.people) = LOWER('campbell-l') AND LOWER(enron_eval_enron_email.mailbox) = LOWER('all_documents')) AS ranked_emails WHERE ranked_emails.`rank` <= 10 ORDER BY ranked_emails.nnn DESC, ranked_emails.`id` DESC
SELECT enron_eval_enron_source.xorigin, enron_eval_enron_source.xfolder, COUNT(1) AS mail_count FROM (SELECT enron_eval_enron_source.xfolder, enron_eval_enron_source.xorigin FROM (SELECT __source.xfolder AS xfolder, __source.xorigin AS xorigin FROM enron_eval.enron_source AS __source) AS enron_eval_enron_source) AS enron_eval_enron_source GROUP BY enron_eval_enron_source.xorigin, enron_eval_enron_source.xfolder ORDER BY mail_count DESC
SELECT ranked_emails.`to`, ranked_emails.rank_num FROM (SELECT e2.`to`, COUNT(1) AS email_count, DENSE_RANK() OVER (ORDER BY COUNT(1) DESC) AS rank_num FROM (SELECT enron_eval_enron_emailinfo.`id`, enron_eval_enron_emailinfo.xfrom FROM (SELECT __source.`id` AS `id`, __source.xfrom AS xfrom FROM enron_eval.enron_emailinfo AS __source) AS enron_eval_enron_emailinfo) AS e1 INNER JOIN (SELECT enron_eval_enron_emailto.`id`, enron_eval_enron_emailto.`to` FROM (SELECT __source.`id` AS `id`, __source.`to` AS `to` FROM enron_eval.enron_emailto AS __source) AS enron_eval_enron_emailto) AS e2 ON e1.`id` = e2.`id` WHERE LOWER(e1.xfrom) = LOWER('Phillip Allen') GROUP BY e2.`to`) AS ranked_emails WHERE ranked_emails.rank_num <= 10
SELECT email_counts.`from`, email_counts.ranking FROM (SELECT enron_eval_enron_emailinfo.`from`, COUNT(1) AS `count`, DENSE_RANK() OVER (ORDER BY COUNT(1) DESC) AS ranking FROM (SELECT enron_eval_enron_emailinfo.body, enron_eval_enron_emailinfo.`from` FROM (SELECT __source.body AS body, __source.`from` AS `from` FROM enron_eval.enron_emailinfo AS __source) AS enron_eval_enron_emailinfo) AS enron_eval_enron_emailinfo WHERE NOT enron_eval_enron_emailinfo.`from` IS NULL AND enron_eval_enron_emailinfo.`from` <> '' AND LOWER(enron_eval_enron_emailinfo.body) LIKE LOWER('%California%') GROUP BY enron_eval_enron_emailinfo.`from`) AS email_counts WHERE email_counts.ranking <= 5
SELECT enron_eval_enron_source.xorigin, COUNT(DISTINCT enron_eval_enron_source.xfolder) AS folder_count FROM (SELECT enron_eval_enron_source.xfolder, enron_eval_enron_source.xorigin FROM (SELECT __source.xfolder AS xfolder, __source.xorigin AS xorigin FROM enron_eval.enron_source AS __source) AS enron_eval_enron_source) AS enron_eval_enron_source WHERE NOT enron_eval_enron_source.xorigin IS NULL AND TRIM(enron_eval_enron_source.xorigin) <> '' AND NOT enron_eval_enron_source.xfolder IS NULL AND TRIM(enron_eval_enron_source.xfolder) <> '' GROUP BY enron_eval_enron_source.xorigin ORDER BY folder_count DESC, CASE WHEN enron_eval_enron_source.xorigin IS NULL THEN 1 ELSE 0 END, enron_eval_enron_source.xorigin ASC
SELECT enron_eval_enron_emailinfo.`from`, AVG(CAST(email_counts.count_per_email AS DOUBLE)) AS avg_recipients FROM (SELECT enron_eval_enron_emailinfo.`from`, enron_eval_enron_emailinfo.`id` FROM (SELECT __source.`from` AS `from`, __source.`id` AS `id` FROM enron_eval.enron_emailinfo AS __source) AS enron_eval_enron_emailinfo) AS enron_eval_enron_emailinfo INNER JOIN (SELECT enron_eval_enron_emailto.`id`, COUNT(1) AS count_per_email FROM (SELECT enron_eval_enron_emailto.`id` FROM (SELECT __source.`id` AS `id` FROM enron_eval.enron_emailto AS __source) AS enron_eval_enron_emailto) AS enron_eval_enron_emailto GROUP BY enron_eval_enron_emailto.`id`) AS email_counts ON enron_eval_enron_emailinfo.`id` = email_counts.`id` WHERE NOT enron_eval_enron_emailinfo.`from` IS NULL AND enron_eval_enron_emailinfo.`from` <> '' GROUP BY enron_eval_enron_emailinfo.`from` HAVING AVG(CAST(email_counts.count_per_email AS DOUBLE)) > 3 ORDER BY avg_recipients DESC
SELECT ROUND(COUNT(DISTINCT CASE WHEN (enron_eval_enron_email.mailbox = 'sent') THEN enron_eval_enron_email.`id` END) * 100.0 / COUNT(DISTINCT enron_eval_enron_email.`id`), 2) FROM (SELECT enron_eval_enron_email.`id`, enron_eval_enron_email.mailbox FROM (SELECT __source.`id` AS `id`, __source.mailbox AS mailbox FROM enron_eval.enron_email AS __source) AS enron_eval_enron_email) AS enron_eval_enron_email
SELECT ranked_emails.`to`, ranked_emails.`count`, ranked_emails.`rank` FROM (SELECT email_to_counts.`to`, email_to_counts.`count`, DENSE_RANK() OVER (ORDER BY email_to_counts.`count` DESC) AS `rank` FROM (SELECT enron_eval_enron_emailto.`to`, COUNT(1) AS `count` FROM (SELECT enron_eval_enron_emailto.`to` FROM (SELECT __source.`to` AS `to` FROM enron_eval.enron_emailto AS __source) AS enron_eval_enron_emailto) AS enron_eval_enron_emailto GROUP BY enron_eval_enron_emailto.`to`) AS email_to_counts) AS ranked_emails WHERE ranked_emails.`rank` = 1
SELECT SUBSTRING(enron_eval_enron_emailinfo.`date`, 6, 2) AS `month`, COUNT(DISTINCT enron_eval_enron_emailinfo.`id`) AS `count` FROM (SELECT enron_eval_enron_emailinfo.`date`, enron_eval_enron_emailinfo.`id` FROM (SELECT __source.`date` AS `date`, __source.`id` AS `id` FROM enron_eval.enron_emailinfo AS __source) AS enron_eval_enron_emailinfo) AS enron_eval_enron_emailinfo WHERE SUBSTRING(enron_eval_enron_emailinfo.`date`, 1, 4) = '2001' GROUP BY SUBSTRING(enron_eval_enron_emailinfo.`date`, 6, 2) ORDER BY CASE WHEN `month` IS NULL THEN 1 ELSE 0 END, `month` ASC
SELECT enron_eval_enron_email.mailbox, COUNT(1) AS `count` FROM (SELECT enron_eval_enron_source.`id`, enron_eval_enron_source.xorigin FROM (SELECT __source.`id` AS `id`, __source.xorigin AS xorigin FROM enron_eval.enron_source AS __source) AS enron_eval_enron_source) AS enron_eval_enron_source INNER JOIN (SELECT enron_eval_enron_emailinfo.`id` FROM (SELECT __source.`id` AS `id` FROM enron_eval.enron_emailinfo AS __source) AS enron_eval_enron_emailinfo) AS enron_eval_enron_emailinfo ON enron_eval_enron_source.`id` = enron_eval_enron_emailinfo.`id` INNER JOIN (SELECT enron_eval_enron_email.`id`, enron_eval_enron_email.mailbox FROM (SELECT __source.`id` AS `id`, __source.mailbox AS mailbox FROM enron_eval.enron_email AS __source) AS enron_eval_enron_email) AS enron_eval_enron_email ON enron_eval_enron_emailinfo.`id` = enron_eval_enron_email.`id` WHERE LOWER(enron_eval_enron_source.xorigin) LIKE LOWER('%allen%') GROUP BY enron_eval_enron_email.mailbox
SELECT ranked_recipients.`to`, ranked_recipients.ranking FROM (SELECT enron_eval_enron_emailto.`to`, COUNT(1) AS `count`, DENSE_RANK() OVER (ORDER BY COUNT(1) DESC) AS ranking FROM (SELECT enron_eval_enron_emailinfo.`from`, enron_eval_enron_emailinfo.`id` FROM (SELECT __source.`from` AS `from`, __source.`id` AS `id` FROM enron_eval.enron_emailinfo AS __source) AS enron_eval_enron_emailinfo) AS enron_eval_enron_emailinfo INNER JOIN (SELECT enron_eval_enron_emailto.`id`, enron_eval_enron_emailto.`to` FROM (SELECT __source.`id` AS `id`, __source.`to` AS `to` FROM enron_eval.enron_emailto AS __source) AS enron_eval_enron_emailto) AS enron_eval_enron_emailto ON enron_eval_enron_emailinfo.`id` = enron_eval_enron_emailto.`id` WHERE LOWER(enron_eval_enron_emailinfo.`from`) LIKE '%phillip.allen%' AND TRIM(enron_eval_enron_emailto.`to`) <> '' GROUP BY enron_eval_enron_emailto.`to`) AS ranked_recipients WHERE ranked_recipients.ranking <= 5
SELECT enron_eval_enron_emailinfo.`id`, enron_eval_enron_emailinfo.subject, max_nthto, max_nthxto FROM (SELECT enron_eval_enron_emailinfo.`id`, enron_eval_enron_emailinfo.subject, COALESCE(CAST(MAX(enron_eval_enron_emailto.nthto) AS SIGNED), 0) AS max_nthto, COALESCE(CAST(MAX(enron_eval_enron_emailxto.nthxto) AS SIGNED), 0) AS max_nthxto, MAX(enron_eval_enron_emailto.nthto), MAX(enron_eval_enron_emailxto.nthxto) FROM (SELECT enron_eval_enron_emailinfo.`id`, enron_eval_enron_emailinfo.subject FROM (SELECT __source.`id` AS `id`, __source.subject AS subject FROM enron_eval.enron_emailinfo AS __source) AS enron_eval_enron_emailinfo) AS enron_eval_enron_emailinfo LEFT OUTER JOIN (SELECT enron_eval_enron_emailto.`id`, enron_eval_enron_emailto.nthto FROM (SELECT __source.`id` AS `id`, __source.nthto AS nthto FROM enron_eval.enron_emailto AS __source) AS enron_eval_enron_emailto) AS enron_eval_enron_emailto ON enron_eval_enron_emailinfo.`id` = enron_eval_enron_emailto.`id` LEFT OUTER JOIN (SELECT enron_eval_enron_emailxto.`id`, enron_eval_enron_emailxto.nthxto FROM (SELECT __source.`id` AS `id`, __source.nthxto AS nthxto FROM enron_eval.enron_emailxto AS __source) AS enron_eval_enron_emailxto) AS enron_eval_enron_emailxto ON enron_eval_enron_emailinfo.`id` = enron_eval_enron_emailxto.`id` GROUP BY enron_eval_enron_emailinfo.`id`, enron_eval_enron_emailinfo.subject ORDER BY GREATEST(COALESCE(CAST(MAX(enron_eval_enron_emailto.nthto) AS SIGNED), 0), COALESCE(CAST(MAX(enron_eval_enron_emailxto.nthxto) AS SIGNED), 0)) DESC, CASE WHEN enron_eval_enron_emailinfo.`id` IS NULL THEN 1 ELSE 0 END, enron_eval_enron_emailinfo.`id` ASC) LIMIT 10
SELECT ranked_to.`to`, ranked_to.`count`, ranked_to.ranking FROM (SELECT e2.`to`, COUNT(1) AS `count`, DENSE_RANK() OVER (ORDER BY COUNT(1) DESC) AS ranking FROM (SELECT enron_eval_enron_emailinfo.`from`, enron_eval_enron_emailinfo.`id` FROM (SELECT __source.`from` AS `from`, __source.`id` AS `id` FROM enron_eval.enron_emailinfo AS __source) AS enron_eval_enron_emailinfo) AS e1 INNER JOIN (SELECT enron_eval_enron_emailto.`id`, enron_eval_enron_emailto.`to` FROM (SELECT __source.`id` AS `id`, __source.`to` AS `to` FROM enron_eval.enron_emailto AS __source) AS enron_eval_enron_emailto) AS e2 ON e1.`id` = e2.`id` WHERE LOWER(e1.`from`) LIKE '%announce%' OR LOWER(e1.`from`) LIKE '%news%' OR LOWER(e1.`from`) LIKE 'enron-%' OR LOWER(e1.`from`) LIKE '%bulletin%' AND NOT e1.`from` IS NULL AND NOT e2.`to` IS NULL GROUP BY e2.`to`) AS ranked_to WHERE ranked_to.ranking <= 5
SELECT ranked_files.xfilename, ranked_files.email_count, ranked_files.rank_num FROM (SELECT enron_eval_enron_source.xfilename, COUNT(DISTINCT enron_eval_enron_source.`id`) AS email_count, DENSE_RANK() OVER (ORDER BY COUNT(DISTINCT enron_eval_enron_source.`id`) DESC, CASE WHEN enron_eval_enron_source.xfilename IS NULL THEN 1 ELSE 0 END, enron_eval_enron_source.xfilename ASC) AS rank_num FROM (SELECT enron_eval_enron_source.`id`, enron_eval_enron_source.xfilename FROM (SELECT __source.`id` AS `id`, __source.xfilename AS xfilename FROM enron_eval.enron_source AS __source) AS enron_eval_enron_source) AS enron_eval_enron_source WHERE NOT enron_eval_enron_source.xfilename IS NULL GROUP BY enron_eval_enron_source.xfilename) AS ranked_files WHERE ranked_files.rank_num <= 5 ORDER BY CASE WHEN ranked_files.rank_num IS NULL THEN 1 ELSE 0 END, ranked_files.rank_num ASC
SELECT ranked_emails.`id`, ranked_emails.to_count, ranked_emails.xto_count, ranked_emails.abs_diff, ranked_emails.to_truncated, ranked_emails.xto_truncated FROM (SELECT email_info_with_counts.`id`, email_info_with_counts.to_count, email_info_with_counts.xto_count, ABS(email_info_with_counts.to_count - email_info_with_counts.xto_count) AS abs_diff, SUBSTRING(email_info_with_counts.to_full, 1, 200) AS to_truncated, SUBSTRING(email_info_with_counts.xto_full, 1, 200) AS xto_truncated, DENSE_RANK() OVER (ORDER BY ABS(email_info_with_counts.to_count - email_info_with_counts.xto_count) DESC, CASE WHEN email_info_with_counts.`id` IS NULL THEN 1 ELSE 0 END, email_info_with_counts.`id` ASC) AS `rank` FROM (SELECT e.`id`, COALESCE(t.to_count, 0) AS to_count, COALESCE(x.xto_count, 0) AS xto_count, e.`to` AS to_full, e.xto AS xto_full FROM (SELECT enron_eval_enron_emailinfo.`id`, enron_eval_enron_emailinfo.`to`, enron_eval_enron_emailinfo.xto FROM (SELECT __source.`id` AS `id`, __source.`to` AS `to`, __source.xto AS xto FROM enron_eval.enron_emailinfo AS __source) AS enron_eval_enron_emailinfo) AS e LEFT OUTER JOIN (SELECT enron_eval_enron_emailto.`id`, COUNT(DISTINCT enron_eval_enron_emailto.`to`) AS to_count FROM (SELECT enron_eval_enron_emailto.`id`, enron_eval_enron_emailto.`to` FROM (SELECT __source.`id` AS `id`, __source.`to` AS `to` FROM enron_eval.enron_emailto AS __source) AS enron_eval_enron_emailto) AS enron_eval_enron_emailto GROUP BY enron_eval_enron_emailto.`id`) AS t ON e.`id` = t.`id` LEFT OUTER JOIN (SELECT enron_eval_enron_emailxto.`id`, COUNT(DISTINCT TRIM(enron_eval_enron_emailxto.xto)) AS xto_count FROM (SELECT enron_eval_enron_emailxto.`id`, enron_eval_enron_emailxto.xto FROM (SELECT __source.`id` AS `id`, __source.xto AS xto FROM enron_eval.enron_emailxto AS __source) AS enron_eval_enron_emailxto) AS enron_eval_enron_emailxto GROUP BY enron_eval_enron_emailxto.`id`) AS x ON e.`id` = x.`id`) AS email_info_with_counts) AS ranked_emails WHERE ranked_emails.`rank` <= 10
