SELECT enron_eval_enron_email.people, COUNT(1) AS `count` FROM (SELECT enron_eval_enron_email.mailbox, enron_eval_enron_email.people FROM (SELECT __source.mailbox AS mailbox, __source.people AS people FROM enron_eval.enron_email AS __source) AS enron_eval_enron_email) AS enron_eval_enron_email WHERE enron_eval_enron_email.mailbox = 'deleted_items' GROUP BY enron_eval_enron_email.people
SELECT enron_eval_enron_emailinfo.`id`, enron_eval_enron_emailinfo.subject, enron_eval_enron_emailorig.subject AS orig_subject, enron_eval_enron_emailorig.`from`, enron_eval_enron_emailorig.`to`, enron_eval_enron_emailorig.xfrom, enron_eval_enron_emailorig.xto FROM (SELECT enron_eval_enron_emailinfo.`id`, enron_eval_enron_emailinfo.subject FROM (SELECT __source.`id` AS `id`, __source.subject AS subject FROM enron_eval.enron_emailinfo AS __source) AS enron_eval_enron_emailinfo) AS enron_eval_enron_emailinfo INNER JOIN (SELECT enron_eval_enron_emailorig.`from`, enron_eval_enron_emailorig.`id`, enron_eval_enron_emailorig.nth, enron_eval_enron_emailorig.subject, enron_eval_enron_emailorig.`to`, enron_eval_enron_emailorig.xfrom, enron_eval_enron_emailorig.xto FROM (SELECT __source.`from` AS `from`, __source.`id` AS `id`, __source.nth AS nth, __source.subject AS subject, __source.`to` AS `to`, __source.xfrom AS xfrom, __source.xto AS xto FROM enron_eval.enron_emailorig AS __source) AS enron_eval_enron_emailorig) AS enron_eval_enron_emailorig ON enron_eval_enron_emailinfo.`id` = enron_eval_enron_emailorig.`id` WHERE LOWER(TRIM(enron_eval_enron_emailinfo.subject)) LIKE 're:%' AND enron_eval_enron_emailorig.nth = 1 ORDER BY CASE WHEN enron_eval_enron_emailinfo.`id` IS NULL THEN 1 ELSE 0 END, enron_eval_enron_emailinfo.`id` ASC
SELECT ranked_addresses.`to`, ranked_addresses.`count` FROM (SELECT enron_eval_enron_emailto.`to`, COUNT(DISTINCT enron_eval_enron_emailinfo.`id`) AS `count`, DENSE_RANK() OVER (ORDER BY COUNT(DISTINCT enron_eval_enron_emailinfo.`id`) DESC, CASE WHEN enron_eval_enron_emailto.`to` IS NULL THEN 1 ELSE 0 END, enron_eval_enron_emailto.`to` ASC) AS `rank` FROM (SELECT enron_eval_enron_emailinfo.`date`, enron_eval_enron_emailinfo.`id` FROM (SELECT __source.`date` AS `date`, __source.`id` AS `id` FROM enron_eval.enron_emailinfo AS __source) AS enron_eval_enron_emailinfo) AS enron_eval_enron_emailinfo INNER JOIN (SELECT enron_eval_enron_emailto.`id`, enron_eval_enron_emailto.`to` FROM (SELECT __source.`id` AS `id`, __source.`to` AS `to` FROM enron_eval.enron_emailto AS __source) AS enron_eval_enron_emailto) AS enron_eval_enron_emailto ON enron_eval_enron_emailinfo.`id` = enron_eval_enron_emailto.`id` WHERE enron_eval_enron_emailinfo.`date` LIKE '2001-10%' GROUP BY enron_eval_enron_emailto.`to`) AS ranked_addresses WHERE ranked_addresses.`rank` <= 5
SELECT COUNT(1) AS `count(*)` FROM (SELECT enron_eval_enron_emailinfo.`from`, enron_eval_enron_emailinfo.`id` FROM (SELECT __source.`from` AS `from`, __source.`id` AS `id` FROM enron_eval.enron_emailinfo AS __source) AS enron_eval_enron_emailinfo) AS e1 INNER JOIN (SELECT enron_eval_enron_email.`id`, enron_eval_enron_email.mailbox FROM (SELECT __source.`id` AS `id`, __source.mailbox AS mailbox FROM enron_eval.enron_email AS __source) AS enron_eval_enron_email) AS e2 ON e1.`id` = e2.`id` WHERE e1.`from` = 'larry.campbell@enron.com' AND e2.mailbox = 'inbox'
SELECT enron_eval_enron_source.xorigin, COUNT(1) AS mail_count, DENSE_RANK() OVER (ORDER BY COUNT(1) DESC) AS ranking FROM (SELECT enron_eval_enron_source.xorigin FROM (SELECT __source.xorigin AS xorigin FROM enron_eval.enron_source AS __source) AS enron_eval_enron_source) AS enron_eval_enron_source WHERE NOT enron_eval_enron_source.xorigin IS NULL AND enron_eval_enron_source.xorigin <> '' GROUP BY enron_eval_enron_source.xorigin HAVING COUNT(1) > 0 ORDER BY CASE WHEN ranking IS NULL THEN 1 ELSE 0 END, ranking ASC LIMIT 5
SELECT COUNT(1) AS `count(*)` FROM (SELECT DISTINCT enron_eval_enron_emailinfo.`from` AS email FROM (SELECT enron_eval_enron_emailinfo.`from` FROM (SELECT __source.`from` AS `from` FROM enron_eval.enron_emailinfo AS __source) AS enron_eval_enron_emailinfo) AS enron_eval_enron_emailinfo WHERE NOT enron_eval_enron_emailinfo.`from` IS NULL AND enron_eval_enron_emailinfo.`from` <> '') AS from_emails INNER JOIN (SELECT DISTINCT enron_eval_enron_emailto.`to` AS email FROM (SELECT enron_eval_enron_emailto.`to` FROM (SELECT __source.`to` AS `to` FROM enron_eval.enron_emailto AS __source) AS enron_eval_enron_emailto) AS enron_eval_enron_emailto WHERE NOT enron_eval_enron_emailto.`to` IS NULL AND enron_eval_enron_emailto.`to` <> '') AS to_emails ON from_emails.email = to_emails.email
SELECT enron_eval_enron_emailinfo.xfrom, COUNT(DISTINCT enron_eval_enron_emailinfo.`id`) AS `count` FROM (SELECT enron_eval_enron_emailinfo.`id`, enron_eval_enron_emailinfo.xfrom FROM (SELECT __source.`id` AS `id`, __source.xfrom AS xfrom FROM enron_eval.enron_emailinfo AS __source) AS enron_eval_enron_emailinfo) AS enron_eval_enron_emailinfo WHERE enron_eval_enron_emailinfo.xfrom IN (SELECT xfrom_only.xfrom FROM (SELECT all_xfrom.xfrom FROM (SELECT DISTINCT enron_eval_enron_emailinfo.xfrom FROM (SELECT enron_eval_enron_emailinfo.xfrom FROM (SELECT __source.xfrom AS xfrom FROM enron_eval.enron_emailinfo AS __source) AS enron_eval_enron_emailinfo) AS enron_eval_enron_emailinfo WHERE NOT enron_eval_enron_emailinfo.xfrom IS NULL AND enron_eval_enron_emailinfo.xfrom <> '') AS all_xfrom WHERE NOT all_xfrom.xfrom IN (SELECT all_xto.xto FROM (SELECT DISTINCT enron_eval_enron_emailinfo.xto FROM (SELECT enron_eval_enron_emailinfo.xto FROM (SELECT __source.xto AS xto FROM enron_eval.enron_emailinfo AS __source) AS enron_eval_enron_emailinfo) AS enron_eval_enron_emailinfo WHERE NOT enron_eval_enron_emailinfo.xto IS NULL AND enron_eval_enron_emailinfo.xto <> '' UNION SELECT DISTINCT enron_eval_enron_emailxto.xto FROM (SELECT enron_eval_enron_emailxto.xto FROM (SELECT __source.xto AS xto FROM enron_eval.enron_emailxto AS __source) AS enron_eval_enron_emailxto) AS enron_eval_enron_emailxto WHERE NOT enron_eval_enron_emailxto.xto IS NULL AND enron_eval_enron_emailxto.xto <> '' UNION SELECT DISTINCT enron_eval_enron_emailorig.xto FROM (SELECT enron_eval_enron_emailorig.xto FROM (SELECT __source.xto AS xto FROM enron_eval.enron_emailorig AS __source) AS enron_eval_enron_emailorig) AS enron_eval_enron_emailorig WHERE NOT enron_eval_enron_emailorig.xto IS NULL AND enron_eval_enron_emailorig.xto <> '') AS all_xto)) AS xfrom_only) GROUP BY enron_eval_enron_emailinfo.xfrom ORDER BY `count` DESC, CASE WHEN enron_eval_enron_emailinfo.xfrom IS NULL THEN 1 ELSE 0 END, enron_eval_enron_emailinfo.xfrom ASC
SELECT subject_counts.subject, subject_counts.`count`, subject_counts.`rank` FROM (SELECT enron_eval_enron_emailinfo.subject, COUNT(1) AS `count`, DENSE_RANK() OVER (ORDER BY COUNT(1) DESC) AS `rank` FROM (SELECT enron_eval_enron_emailinfo.subject FROM (SELECT __source.subject AS subject FROM enron_eval.enron_emailinfo AS __source) AS enron_eval_enron_emailinfo) AS enron_eval_enron_emailinfo WHERE NOT enron_eval_enron_emailinfo.subject IS NULL AND TRIM(enron_eval_enron_emailinfo.subject) <> '' GROUP BY enron_eval_enron_emailinfo.subject) AS subject_counts WHERE subject_counts.`rank` <= 3
SELECT ranked_emails.people, ranked_emails.`from`, ranked_emails.email_count, ranked_emails.`rank` FROM (SELECT email_counts.people, email_counts.`from`, email_counts.email_count, DENSE_RANK() OVER (PARTITION BY email_counts.people ORDER BY email_counts.email_count DESC, CASE WHEN email_counts.`from` IS NULL THEN 1 ELSE 0 END, email_counts.`from` ASC) AS `rank` FROM (SELECT e.people, ei.`from`, COUNT(DISTINCT ei.`id`) AS email_count FROM (SELECT enron_eval_enron_email.`id`, enron_eval_enron_email.people FROM (SELECT __source.`id` AS `id`, __source.people AS people FROM enron_eval.enron_email AS __source) AS enron_eval_enron_email) AS e INNER JOIN (SELECT enron_eval_enron_emailinfo.`from`, enron_eval_enron_emailinfo.`id` FROM (SELECT __source.`from` AS `from`, __source.`id` AS `id` FROM enron_eval.enron_emailinfo AS __source) AS enron_eval_enron_emailinfo) AS ei ON e.`id` = ei.`id` WHERE NOT e.people IS NULL AND TRIM(e.people) <> '' AND NOT ei.`from` IS NULL AND TRIM(ei.`from`) <> '' GROUP BY e.people, ei.`from`) AS email_counts) AS ranked_emails WHERE ranked_emails.`rank` <= 3 ORDER BY CASE WHEN ranked_emails.people IS NULL THEN 1 ELSE 0 END, ranked_emails.people ASC, CASE WHEN ranked_emails.`rank` IS NULL THEN 1 ELSE 0 END, ranked_emails.`rank` ASC
SELECT sender_rank.`date`, sender_rank.`from`, sender_rank.`rank` FROM (SELECT d.`date`, enron_eval_enron_emailinfo.`from`, COUNT(1) AS send_count, DENSE_RANK() OVER (ORDER BY COUNT(1) DESC) AS `rank` FROM (SELECT enron_eval_enron_emailinfo.`date`, enron_eval_enron_emailinfo.`from` FROM (SELECT __source.`date` AS `date`, __source.`from` AS `from` FROM enron_eval.enron_emailinfo AS __source) AS enron_eval_enron_emailinfo) AS enron_eval_enron_emailinfo INNER JOIN (SELECT SUBSTRING(enron_eval_enron_emailinfo.`date`, 1, 10) AS `date`, COUNT(1) AS `count` FROM (SELECT enron_eval_enron_emailinfo.`date`, enron_eval_enron_emailinfo.`from` FROM (SELECT __source.`date` AS `date`, __source.`from` AS `from` FROM enron_eval.enron_emailinfo AS __source) AS enron_eval_enron_emailinfo) AS enron_eval_enron_emailinfo GROUP BY SUBSTRING(enron_eval_enron_emailinfo.`date`, 1, 10) ORDER BY `count` DESC LIMIT 1) AS d ON SUBSTRING(enron_eval_enron_emailinfo.`date`, 1, 10) = d.`date` GROUP BY d.`date`, enron_eval_enron_emailinfo.`from`, d.`count`) AS sender_rank WHERE sender_rank.`rank` <= 5
SELECT cc.category, cc.`count`, ROUND(cc.`count` * 100.0 / tc.total, 2) AS percentage FROM (SELECT valid_emails.category, COUNT(1) AS `count` FROM (SELECT enron_eval_enron_emailinfo.`from`, CASE WHEN ((NOT enron_eval_enron_emailinfo.`from` IS NULL AND (TRIM(enron_eval_enron_emailinfo.`from`) <> '')) AND LOWER(TRIM(enron_eval_enron_emailinfo.`from`)) LIKE '%@enron.com') THEN 'internal' WHEN (NOT enron_eval_enron_emailinfo.`from` IS NULL AND (TRIM(enron_eval_enron_emailinfo.`from`) <> '')) THEN 'external' ELSE NULL END AS category FROM (SELECT enron_eval_enron_emailinfo.`from` FROM (SELECT __source.`from` AS `from` FROM enron_eval.enron_emailinfo AS __source) AS enron_eval_enron_emailinfo) AS enron_eval_enron_emailinfo) AS valid_emails WHERE NOT valid_emails.category IS NULL GROUP BY valid_emails.category) AS cc CROSS JOIN (SELECT COUNT(1) AS total FROM (SELECT enron_eval_enron_emailinfo.`from`, CASE WHEN ((NOT enron_eval_enron_emailinfo.`from` IS NULL AND (TRIM(enron_eval_enron_emailinfo.`from`) <> '')) AND LOWER(TRIM(enron_eval_enron_emailinfo.`from`)) LIKE '%@enron.com') THEN 'internal' WHEN (NOT enron_eval_enron_emailinfo.`from` IS NULL AND (TRIM(enron_eval_enron_emailinfo.`from`) <> '')) THEN 'external' ELSE NULL END AS category FROM (SELECT enron_eval_enron_emailinfo.`from` FROM (SELECT __source.`from` AS `from` FROM enron_eval.enron_emailinfo AS __source) AS enron_eval_enron_emailinfo) AS enron_eval_enron_emailinfo) AS valid_emails WHERE NOT valid_emails.category IS NULL) AS tc ORDER BY CASE WHEN cc.category IS NULL THEN 1 ELSE 0 END, cc.category ASC
SELECT address_counts.address, address_counts.people_count FROM (SELECT unique_people_addresses.address, COUNT(DISTINCT unique_people_addresses.people) AS people_count FROM (SELECT DISTINCT people_addresses.people, people_addresses.address FROM (SELECT e.people, LOWER(TRIM(ei.`from`)) AS address FROM (SELECT enron_eval_enron_email.`id`, enron_eval_enron_email.people FROM (SELECT __source.`id` AS `id`, __source.people AS people FROM enron_eval.enron_email AS __source) AS enron_eval_enron_email) AS e INNER JOIN (SELECT enron_eval_enron_emailinfo.`from`, enron_eval_enron_emailinfo.`id` FROM (SELECT __source.`from` AS `from`, __source.`id` AS `id` FROM enron_eval.enron_emailinfo AS __source) AS enron_eval_enron_emailinfo) AS ei ON e.`id` = ei.`id` WHERE e.people IN ('campbell-l', 'allen-p', 'badeer-r') AND NOT ei.`from` IS NULL AND TRIM(ei.`from`) <> '' UNION ALL SELECT e.people, LOWER(TRIM(et.`to`)) AS address FROM (SELECT enron_eval_enron_email.`id`, enron_eval_enron_email.people FROM (SELECT __source.`id` AS `id`, __source.people AS people FROM enron_eval.enron_email AS __source) AS enron_eval_enron_email) AS e INNER JOIN (SELECT enron_eval_enron_emailto.`id`, enron_eval_enron_emailto.`to` FROM (SELECT __source.`id` AS `id`, __source.`to` AS `to` FROM enron_eval.enron_emailto AS __source) AS enron_eval_enron_emailto) AS et ON e.`id` = et.`id` WHERE e.people IN ('campbell-l', 'allen-p', 'badeer-r') AND NOT et.`to` IS NULL AND TRIM(et.`to`) <> '') AS people_addresses) AS unique_people_addresses GROUP BY unique_people_addresses.address HAVING COUNT(DISTINCT unique_people_addresses.people) >= 2) AS address_counts ORDER BY address_counts.people_count DESC, CASE WHEN address_counts.address IS NULL THEN 1 ELSE 0 END, address_counts.address ASC
SELECT larry_emails.`to`, larry_emails.larry_count, phillip_emails.phillip_count FROM (SELECT enron_eval_enron_emailto.`to`, COUNT(1) AS larry_count FROM (SELECT enron_eval_enron_emailto.`id`, enron_eval_enron_emailto.`to` FROM (SELECT __source.`id` AS `id`, __source.`to` AS `to` FROM enron_eval.enron_emailto AS __source) AS enron_eval_enron_emailto) AS enron_eval_enron_emailto INNER JOIN (SELECT enron_eval_enron_emailinfo.`id`, enron_eval_enron_emailinfo.xfrom FROM (SELECT __source.`id` AS `id`, __source.xfrom AS xfrom FROM enron_eval.enron_emailinfo AS __source) AS enron_eval_enron_emailinfo) AS enron_eval_enron_emailinfo ON enron_eval_enron_emailto.`id` = enron_eval_enron_emailinfo.`id` WHERE LOWER(enron_eval_enron_emailinfo.xfrom) = LOWER('Larry Campbell') GROUP BY enron_eval_enron_emailto.`to`) AS larry_emails INNER JOIN (SELECT enron_eval_enron_emailto.`to`, COUNT(1) AS phillip_count FROM (SELECT enron_eval_enron_emailto.`id`, enron_eval_enron_emailto.`to` FROM (SELECT __source.`id` AS `id`, __source.`to` AS `to` FROM enron_eval.enron_emailto AS __source) AS enron_eval_enron_emailto) AS enron_eval_enron_emailto INNER JOIN (SELECT enron_eval_enron_emailinfo.`id`, enron_eval_enron_emailinfo.xfrom FROM (SELECT __source.`id` AS `id`, __source.xfrom AS xfrom FROM enron_eval.enron_emailinfo AS __source) AS enron_eval_enron_emailinfo) AS enron_eval_enron_emailinfo ON enron_eval_enron_emailto.`id` = enron_eval_enron_emailinfo.`id` WHERE LOWER(enron_eval_enron_emailinfo.xfrom) = LOWER('Phillip Allen') GROUP BY enron_eval_enron_emailto.`to`) AS phillip_emails ON larry_emails.`to` = phillip_emails.`to` ORDER BY CASE WHEN larry_emails.`to` IS NULL THEN 1 ELSE 0 END, larry_emails.`to` ASC
SELECT ROUND(AVG(CAST(grouped.head_count AS DOUBLE)), 4) AS average_history_headers, MAX(grouped.head_count) AS max_history_headers, SUM(CASE WHEN (grouped.head_count >= 3) THEN 1 ELSE 0 END) AS count_with_at_least_3 FROM (SELECT enron_eval_enron_emailorig.`id`, COUNT(1) AS head_count FROM (SELECT enron_eval_enron_emailorig.`id` FROM (SELECT __source.`id` AS `id` FROM enron_eval.enron_emailorig AS __source) AS enron_eval_enron_emailorig) AS enron_eval_enron_emailorig GROUP BY enron_eval_enron_emailorig.`id`) AS grouped
SELECT ranked_mailboxes.people, ranked_mailboxes.mailbox, ranked_mailboxes.mail_count FROM (SELECT mailbox_counts.people, mailbox_counts.mailbox, mailbox_counts.mail_count, DENSE_RANK() OVER (PARTITION BY mailbox_counts.people ORDER BY mailbox_counts.mail_count DESC) AS `rank` FROM (SELECT enron_eval_enron_email.people, enron_eval_enron_email.mailbox, COUNT(1) AS mail_count FROM (SELECT enron_eval_enron_email.mailbox, enron_eval_enron_email.people FROM (SELECT __source.mailbox AS mailbox, __source.people AS people FROM enron_eval.enron_email AS __source) AS enron_eval_enron_email) AS enron_eval_enron_email WHERE NOT enron_eval_enron_email.people IS NULL GROUP BY enron_eval_enron_email.people, enron_eval_enron_email.mailbox) AS mailbox_counts) AS ranked_mailboxes WHERE ranked_mailboxes.`rank` = 1 ORDER BY CASE WHEN ranked_mailboxes.people IS NULL THEN 1 ELSE 0 END, ranked_mailboxes.people ASC, CASE WHEN ranked_mailboxes.mailbox IS NULL THEN 1 ELSE 0 END, ranked_mailboxes.mailbox ASC
